-- Retro Play PostgreSQL schema v1. Uses ISO-8601 text timestamps deliberately to preserve existing comparisons.
BEGIN;
CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, avatar TEXT NOT NULL DEFAULT '🌷', is_kid INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, profile_id BIGINT REFERENCES profiles(id) ON DELETE SET NULL, csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscription_plans (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, price_cents INTEGER NOT NULL, duration_days INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS movies (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, synopsis TEXT NOT NULL, year INTEGER NOT NULL, duration_sec INTEGER NOT NULL DEFAULT 300, age_rating INTEGER NOT NULL DEFAULT 0, director TEXT NOT NULL DEFAULT '', cast_text TEXT NOT NULL DEFAULT '', access_type TEXT NOT NULL CHECK(access_type IN ('free','subscription','rental','both')), rental_cents INTEGER NOT NULL DEFAULT 790, rental_start_days INTEGER NOT NULL DEFAULT 30, rental_watch_hours INTEGER NOT NULL DEFAULT 48, poster TEXT NOT NULL, banner TEXT NOT NULL, video_file TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, demo INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS genres (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS movie_genres (movie_id BIGINT REFERENCES movies(id) ON DELETE CASCADE, genre_id BIGINT REFERENCES genres(id) ON DELETE CASCADE, PRIMARY KEY(movie_id,genre_id));
CREATE TABLE IF NOT EXISTS series (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL UNIQUE, synopsis TEXT NOT NULL DEFAULT '', published INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS episodes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, series_id BIGINT REFERENCES series(id) ON DELETE CASCADE, season INTEGER NOT NULL, number INTEGER NOT NULL, title TEXT NOT NULL, video_file TEXT, movie_id BIGINT REFERENCES movies(id), UNIQUE(series_id,season,number));
CREATE TABLE IF NOT EXISTS payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('rental','subscription')), product_id BIGINT NOT NULL, amount_cents INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', provider TEXT NOT NULL DEFAULT 'internal_sandbox', external_reference TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), plan_id BIGINT NOT NULL REFERENCES subscription_plans(id), payment_id BIGINT REFERENCES payments(id), status TEXT NOT NULL, starts_at TEXT NOT NULL, expires_at TEXT NOT NULL, auto_renew INTEGER NOT NULL DEFAULT 0, cancel_requested_at TEXT);
CREATE TABLE IF NOT EXISTS rentals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), movie_id BIGINT NOT NULL REFERENCES movies(id), payment_id BIGINT NOT NULL UNIQUE REFERENCES payments(id), purchased_at TEXT NOT NULL, start_by TEXT NOT NULL, started_at TEXT, expires_at TEXT);
CREATE TABLE IF NOT EXISTS favorites (profile_id BIGINT REFERENCES profiles(id) ON DELETE CASCADE, movie_id BIGINT REFERENCES movies(id) ON DELETE CASCADE, PRIMARY KEY(profile_id,movie_id));
CREATE TABLE IF NOT EXISTS watch_progress (profile_id BIGINT REFERENCES profiles(id) ON DELETE CASCADE, movie_id BIGINT REFERENCES movies(id) ON DELETE CASCADE, position_sec DOUBLE PRECISION NOT NULL, updated_at TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(profile_id,movie_id));
CREATE TABLE IF NOT EXISTS watch_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT REFERENCES profiles(id) ON DELETE CASCADE, movie_id BIGINT REFERENCES movies(id) ON DELETE CASCADE, watched_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (profile_id BIGINT REFERENCES profiles(id) ON DELETE CASCADE, movie_id BIGINT REFERENCES movies(id) ON DELETE CASCADE, stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5), body TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, PRIMARY KEY(profile_id,movie_id));
CREATE TABLE IF NOT EXISTS achievements (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, title TEXT NOT NULL, icon TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements (profile_id BIGINT REFERENCES profiles(id) ON DELETE CASCADE, achievement_id BIGINT REFERENCES achievements(id) ON DELETE CASCADE, awarded_at TEXT NOT NULL, PRIMARY KEY(profile_id,achievement_id));
CREATE TABLE IF NOT EXISTS banners (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, movie_id BIGINT REFERENCES movies(id), active INTEGER DEFAULT 1, position INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS video_assets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, movie_id BIGINT REFERENCES movies(id), format TEXT NOT NULL, path TEXT NOT NULL, resolution TEXT, status TEXT NOT NULL DEFAULT 'ready');
CREATE INDEX IF NOT EXISTS idx_movies_year ON movies(year);
CREATE INDEX IF NOT EXISTS idx_movies_access ON movies(access_type,published);
CREATE INDEX IF NOT EXISTS idx_profiles_owner ON profiles(user_id);
CREATE INDEX IF NOT EXISTS idx_payments_owner ON payments(user_id,status);
CREATE INDEX IF NOT EXISTS idx_rentals_owner ON rentals(user_id,movie_id);
CREATE INDEX IF NOT EXISTS idx_progress_profile ON watch_progress(profile_id,updated_at);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
COMMIT;
